package requesttiming

import (
	"bytes"
	"context"

	"github.com/tidwall/gjson"
)

type outerDeliveryKey struct{}

// WithOuterDelivery delegates delivery observations to a surrounding response
// adapter. Acceptance into an inner adapter is not a downstream write.
func WithOuterDelivery(ctx context.Context) context.Context {
	return context.WithValue(ctx, outerDeliveryKey{}, true)
}

// DeliveredSSE observes JSON events generated by a bridge after a successful
// downstream write. Offsets describe application writes, not client receipt.
// No content, tool arguments or identifiers are retained.
func DeliveredSSE(ctx context.Context, wire []byte) {
	if From(ctx) == nil || ctx.Value(outerDeliveryKey{}) != nil {
		return
	}
	for len(wire) > 0 {
		line, rest, _ := bytes.Cut(wire, []byte("\n"))
		wire = rest
		data, ok := bytes.CutPrefix(line, []byte("data: "))
		if !ok || !gjson.ValidBytes(data) {
			continue
		}
		Delivered(ctx, data)
	}
}

// Delivered accepts one complete generated Chat, Gemini or Responses JSON event.
func Delivered(ctx context.Context, data []byte) {
	if From(ctx) == nil || ctx.Value(outerDeliveryKey{}) != nil {
		return
	}
	text, tool, reasoning, terminal := false, false, false, false
	for _, choice := range gjson.GetBytes(data, "choices").Array() {
		text = text || choice.Get("delta.content").String() != ""
		tool = tool || len(choice.Get("delta.tool_calls").Array()) > 0
		reasoning = reasoning || choice.Get("delta.reasoning_content").String() != ""
		terminal = terminal || choice.Get("finish_reason").String() != ""
	}
	for _, candidate := range gjson.GetBytes(data, "candidates").Array() {
		terminal = terminal || candidate.Get("finishReason").String() != ""
		for _, part := range candidate.Get("content.parts").Array() {
			thought := part.Get("thought").Bool()
			text = text || (!thought && part.Get("text").String() != "")
			reasoning = reasoning || (thought && part.Get("text").String() != "")
			tool = tool || part.Get("functionCall").Exists()
		}
	}
	switch gjson.GetBytes(data, "type").String() {
	case "response.output_text.delta":
		text = gjson.GetBytes(data, "delta").String() != ""
	case "response.function_call_arguments.delta":
		tool = gjson.GetBytes(data, "delta").String() != ""
	case "response.reasoning_text.delta", "response.reasoning_summary_text.delta":
		reasoning = gjson.GetBytes(data, "delta").String() != ""
	case "response.completed", "response.incomplete", "response.failed":
		terminal = true
	}
	if text {
		Mark(ctx, "downstream_first_text_write")
	}
	if tool {
		Mark(ctx, "downstream_first_tool_write")
	}
	if reasoning {
		Mark(ctx, "downstream_first_reasoning_write")
	}
	if terminal {
		Mark(ctx, "downstream_first_terminal_write")
	}
}
